228	    /**
229	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
230	     * present, otherwise {@code "PHONE"}.
231	     */
232	    @Transient
233	    public String getContactPreference() {
234	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
235	    }
236	
237	    /**
238	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
239	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
240	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
241	     * date to measure against) is available.
242	     */
243	    @Transient
244	    public String getAgeBand() {
245	        if (this.birthDate == null || this.registrationDate == null) {
246	            return null;
247	        }
248	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
249	        if (age < 18) {
250	            return "MINOR";
251	        }
252	        if (age < 65) {
253	            return "ADULT";
254	        }
255	        return "SENIOR";
256	    }
257	
258	    /**
259	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
260	     * {@link #customerCode}, derived on read.
261	     */
262	    @Transient
263	    public Integer getCheckDigit() {
264	        return luhnCheckDigit(this.customerCode);
265	    }
266	
267	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
268	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
269	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
270	        "NSW", new int[] {2000, 2099},
271	        "VIC", new int[] {3000, 3099},
272	        "QLD", new int[] {4000, 4099});
273	
274	    /**
275	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
276	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
277	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
278	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
279	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
280	     */
281	    @Transient
282	    public String getRegion() {
283	        String byPostcode = regionForPostcode(this.postcode);
284	        if (byPostcode != null) {
285	            return byPostcode;
286	        }
287	        if ("Sydney".equals(this.city)) {
288	            return "NSW";
289	        }
290	        if ("Melbourne".equals(this.city)) {
291	            return "VIC";
292	        }
293	        if ("Brisbane".equals(this.city)) {
294	            return "QLD";
295	        }
296	        return "UNKNOWN";
297	    }
298	
299	    /**
300	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
301	     * customer code}: the region segment before the first '-' of the customer code
302	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
303	     * code has been assigned yet.
304	     */
305	    @Transient
306	    public String getLocality() {
307	        if (this.customerCode != null) {
308	            int dash = this.customerCode.indexOf('-');
309	            if (dash > 0) {
310	                return this.customerCode.substring(0, dash);
311	            }
312	        }
313	        return getRegion();
314	    }
315	
316	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
317	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
318	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
319	    public static int[] postcodeRangeForRegion(String region) {
320	        return REGION_POSTCODE_RANGES.get(region);
321	    }
322	
323	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
324	     *  absent, not a 4-digit value, or in no known range. */
325	    private static String regionForPostcode(String postcode) {
326	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
327	            return null;
328	        }
329	        int value = Integer.parseInt(postcode);
330	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
331	            int[] range = entry.getValue();
332	            if (value >= range[0] && value <= range[1]) {
333	                return entry.getKey();
334	            }
335	        }
336	        return null;
337	    }
338	
339	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
340	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
341	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
342	     *  {@code +1}), so a number matches at most one. */
343	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
344	        "+61", 9, "+1", 10);
345	
346	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
347	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
348	    public static String countryCodeOf(String telephone) {
349	        if (telephone == null) {
350	            return null;
351	        }
352	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
353	            if (telephone.startsWith(countryCode)) {
354	                return countryCode;
355	            }
356	        }
357	        return null;
358	    }
359	
360	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
361	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
362	     *  {@code +1 => 10}). */
363	    public static Integer nationalNumberLength(String countryCode) {
364	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
365	    }
366	
367	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
368	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
369	     *  digit-free value yields {@code 0}. */
370	    private static int luhnCheckDigit(String value) {
371	        int sum = 0;
372	        boolean doubling = true;
373	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
374	            char c = value.charAt(i);
375	            if (c < '0' || c > '9') {
376	                continue;
377	            }
378	            int digit = c - '0';
379	            if (doubling) {
380	                digit *= 2;
381	                if (digit > 9) {
382	                    digit -= 9;
383	                }
384	            }
385	            sum += digit;
386	            doubling = !doubling;
387	        }
388	        return (10 - (sum % 10)) % 10;
389	    }
390	
391	    protected Set<Pet> getPetsInternal() {
392	        if (this.pets == null) {
393	            this.pets = new HashSet<>();
394	        }
395	        return this.pets;
396	    }
397	
398	    protected void setPetsInternal(Set<Pet> pets) {
399	        this.pets = pets;
400	    }
401	
402	    public List<Pet> getPets() {
403	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
404	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
405	        return Collections.unmodifiableList(sortedPets);
406	    }
407	
408	    public void setPets(List<Pet> pets) {
409	        this.pets = new HashSet<>(pets);
410	    }
411	
412	    public void addPet(Pet pet) {
413	        getPetsInternal().add(pet);
414	        pet.setOwner(this);
415	    }
416	
417	    /**
418	     * Return the Pet with the given name, or null if none found for this Owner.
419	     *
420	     * @param name to test
421	     * @return true if pet name is already in use
422	     */
423	    public Pet getPet(String name) {
424	        return getPet(name, false);
425	    }
426	
427	    /**
428	     * Return the Pet with the given name, or null if none found for this Owner.
429	     *
430	     * @param name to test
431	     * @return true if pet name is already in use
432	     */
433	    public Pet getPet(String name, boolean ignoreNew) {
434	        name = name.toLowerCase();
435	        for (Pet pet : getPetsInternal()) {
436	            if (!ignoreNew || !pet.isNew()) {
437	                String compName = pet.getName();
438	                compName = compName.toLowerCase();
439	                if (compName.equals(name)) {
440	                    return pet;
441	                }
442	            }
443	        }
444	        return null;
445	    }
446	
447	    public Pet getPet(Integer petId) {
448	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
449	    }
450	
451	    @Override
452	    public String toString() {
453	        return new ToStringCreator(this)
454	
455	            .append("id", this.getId())
456	            .append("new", this.isNew())
457	            .append("lastName", this.getLastName())
458	            .append("firstName", this.getFirstName())
459	            .append("address", this.address)
460	            .append("city", this.city)
461	            .append("telephone", this.telephone)
462	            .toString();
463	    }
464	}
